INSERT INTO students (id, tenant_id, full_name, student_number, status)
SELECT
  ('00000000-0000-0000-0200-' || lpad(n::text, 12, '0'))::uuid,
  '00000000-0000-0000-0000-000000020001',
  trim(both from (
    (ARRAY['Defne Yılmaz','Efe Demir','Mina Kaya','Aras Çelik','Elif Aydın','Can Koç','Zeynep Şahin','Emir Polat','Selin Güneş','Kerem Akın'])[1 + ((n - 1) % 10)]
    || ' ' || n::text
  )),
  'PRI' || lpad(n::text, 4, '0'),
  'active'
FROM generate_series(1, 200) AS n
WHERE NOT EXISTS (
  SELECT 1 FROM students WHERE tenant_id = '00000000-0000-0000-0000-000000020001' AND student_number = 'PRI' || lpad(n::text, 4, '0')
);

